<?php
require_once __DIR__.'/../includes/database.php';require_once __DIR__.'/../includes/catalog-reference.php';
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);initialize_database($db);$_SESSION=[];
function ref_check($ok,$message){if(!$ok)throw new RuntimeException($message);}
foreach(['One','Other'] as $name)stock_query($db,'INSERT INTO users(name,email,password_hash) VALUES(?,?,?)',[$name,strtolower($name).'@example.invalid','x']);
stock_query($db,'INSERT INTO pallet_labels(code,reserved_by,reserved_until) VALUES(?,1,?)',['12345678',time()+86400]);$p=stock_claim($db,'12345678',1);
foreach(['96385074','4006381333931','5901234123457'] as $ean)stock_query($db,"INSERT INTO product_lookup_state(ean,state,checked_at,token) VALUES(?,'missing',1000,'test')",[$ean]);
$input=['operation_key'=>'11111111-1111-4111-8111-111111111111','ean'=>'96385074','name'=>'Referencia nueva','code'=>'12345678','pallet_id'=>$p['id'],'action'=>'save_product','product_id'=>0,'amount'=>3,'kind'=>'units','pack_size'=>1,'expires'=>'','offline_created'=>1000200];
$proof=catalog_reference_prepare($db,1,$input,1000);$permit=catalog_reference_take(1,[...$input,'catalog_permit'=>$proof['permit']],1000.2);ref_check($permit!==null,'fast bound permit');ref_check(catalog_reference_take(1,[...$input,'catalog_permit'=>$proof['permit']],1000.3)===null,'single use');
$db->beginTransaction();$result=stock_save_product($db,1,$input);ref_check(catalog_reference_insert($db,1,$permit,$result),'insert from confirmed movement');$db->commit();$product=catalog_product($db,$input['ean']);ref_check($product['source']==='stock_reference'&&$product['name']===$input['name'],'source/reference');ref_check(!catalog_reference_insert($db,1,$permit,$result),'no overwrite');
foreach(['scan_events','report_rewards','product_edits','ranking_daily'] as $table)ref_check((int)$db->query('SELECT COUNT(*) FROM '.$table)->fetchColumn()===0,'no extra rank/edit '.$table);
$input['ean']='4006381333931';$input['operation_key']='22222222-2222-4222-8222-222222222222';$proof=catalog_reference_prepare($db,1,$input,1000);ref_check(catalog_reference_take(1,[...$input,'catalog_permit'=>$proof['permit']],1004)===null,'slow permit denied');
$proof=catalog_reference_prepare($db,1,$input,1000);ref_check(catalog_reference_take(1,[...$input,'offline_created'=>900000,'catalog_permit'=>$proof['permit']],1000.5)===null,'old offline movement denied');
$proof=catalog_reference_prepare($db,1,$input,1000);ref_check(catalog_reference_take(2,[...$input,'catalog_permit'=>$proof['permit']],1000.5)===null,'account mismatch denied');
$proof=catalog_reference_prepare($db,1,$input,1000);ref_check(catalog_reference_take(1,[...$input,'name'=>'Changed','catalog_permit'=>$proof['permit']],1000.5)===null,'payload mismatch denied');
$proof=catalog_reference_prepare($db,1,$input,1000);$permit=catalog_reference_take(1,[...$input,'catalog_permit'=>$proof['permit']],1000.2);$db->beginTransaction();$result=stock_save_product($db,1,$input);ref_check(catalog_reference_insert($db,1,$permit,$result),'transactional catalog');$db->rollBack();ref_check(catalog_product($db,$input['ean'])===null,'rollback no catalog');ref_check(!stock_query($db,'SELECT 1 FROM pallet_products WHERE ean=?',[$input['ean']])->fetchColumn(),'rollback no merchandise');
try{catalog_reference_prepare($db,2,$input,1000);throw new RuntimeException('unauthorized accepted');}catch(CatalogException $e){ref_check($e->status===403,'ownership');}
stock_query($db,"UPDATE product_lookup_state SET state='pending' WHERE ean=?",[$input['ean']]);try{catalog_reference_prepare($db,1,$input,1000);throw new RuntimeException('unverified API accepted');}catch(CatalogException $e){ref_check($e->status===409,'missing must be definitive');}
echo "OK: authoritative missing lookup, timed one-use permit, user/payload/original-time checks, catalog+stock transaction, rollback, conflict no overwrite and no TOP/reward/edit events.\n";
